<?php declare(strict_types=1);use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;$years=[];foreach($rows as$r)$years[]=substr((string)$r['report_date'],0,4);$years=array_values(array_unique($years));sort($years);$query=Yii::$app->request->get();ViewSupport::begin($this,'Расчёты ОТиЗ',$identity,'otiz','wide');?>
<main class="fm2-otiz fm2-otiz-page"><header class="fm2-page-header"><div><h1>Расчёты ОТиЗ</h1><p>Единый реестр черновиков, обязательств и истории выплат</p></div><form method="post" action="/pilot/otiz/calculations"><input type="hidden" name="_csrf" value="<?=Html::encode($csrf)?>"><input type="hidden" name="operationId" value="<?=ViewSupport::uuid()?>"><label>Расчётная дата<input class="shlz-input" type="date" name="reportDate" required></label><button class="shlz-button shlz-button--primary" type="submit">Новый расчёт</button></form></header><nav class="fm2-otiz-v2-tabs" aria-label="Фильтры расчётов"><a href="?filter=waiting&amp;year=<?=Html::encode((string)($query['year']??'all'))?>">Ожидают выплаты</a><a href="?filter=drafts&amp;year=<?=Html::encode((string)($query['year']??'all'))?>">Черновики</a><a href="?filter=history&amp;year=<?=Html::encode((string)($query['year']??'all'))?>">История</a><a href="?filter=all&amp;year=<?=Html::encode((string)($query['year']??'all'))?>">Все</a></nav><form method="get" action="/pilot/otiz/payments"><input type="hidden" name="filter" value="<?=Html::encode((string)($query['filter']??'waiting'))?>"><label>Год<select name="year"><option value="all">Все годы</option><option value="none">Без года</option><?php foreach($years as$year):?><option value="<?=$year?>"<?=($query['year']??'all')===$year?' selected':''?>><?=$year?></option><?php endforeach?></select></label><button class="shlz-button shlz-button--secondary" type="submit">Показать</button></form><section class="fm2-otiz-surface"><div class="shlz-table-wrap" tabindex="0"><table class="shlz-table"><thead><tr><th>Расчёт</th><th>Дата</th><th>Статус</th><th>Начислено</th><th>Выплачено</th><th>Остаток / причина</th></tr></thead><tbody><?php foreach($rows as$r):$p=json_decode((string)$r['projection_json'],true);$total=(int)($p['totalCents']??0);?><tr><td><a href="/pilot/otiz/calculations/<?=(int)$r['id']?>">Расчёт #<?=(int)$r['id']?></a></td><td><?=Html::encode((string)$r['report_date'])?></td><td><?=Html::encode((string)$r['status'])?></td><td><?=number_format($total/100,2,',',' ')?> ₽</td><td><?=number_format((int)($r['paid_cents']??0)/100,2,',',' ')?> ₽</td><td><?=number_format(max(0,$total-(int)($r['paid_cents']??0))/100,2,',',' ')?> ₽<?=($r['status']==='cancelled'?' · расчёт отменён':'')?></td></tr><?php endforeach?></tbody></table></div></section><?=ViewSupport::pagination('/pilot/otiz/payments',$page,$pages,$total,$pageSize,['filter'=>$query['filter']??'waiting','year'=>$query['year']??'all'],'Страницы расчётов ОТиЗ')?></main><?php ViewSupport::end($this);?>
